// Proves the per-user accounts (generated by server/mbox-admin.sh) against a real nats-server:
// what a user must NOT be able to do, and what they must be able to do. Two attackers: alice, with
// the permission block the script generates, and mallory, whose permission block the test strips
// so that her account's imports are the only boundary (the block is defense in depth).
import assert from 'node:assert/strict';
import { after, before } from 'node:test';
import { headers, connect, type NatsConnection } from '@nats-io/transport-node';
import {
  jetstream,
  jetstreamManager,
  type JetStreamClient,
  type JetStreamManager,
} from '@nats-io/jetstream';
import fs from 'node:fs';
import path from 'node:path';
import { areaToken } from '../src/core/transport/nats.js';
import { Broker, findServer, sleep } from './helpers.js';
import { describe, it } from './suite.js';

const SERVER = findServer();
const enc = (o: unknown): string => (typeof o === 'string' ? o : JSON.stringify(o));
const STREAMS = [
  'MBX_ALICE',
  'MBX_BOB',
  'MBX_MALLORY',
  'MBX_ALL',
  'KV_presence',
  'EVT_ALICE',
  'EVT_BOB',
  'EVT_MALLORY',
  'KV_sharing',
  'ASKS',
];
/** The subject token of an area, as the client computes it. */
const T = areaToken('repo:github.com/acme/web');
/** bob's claim on his service address bob.helpdesk (a presence-bucket entry only bob may write). */
const BOB_CLAIM_SUBJECT = '$KV.presence.bob._svc.helpdesk';
const BOB_CLAIM = JSON.stringify({
  service: 'bob.helpdesk',
  holder: 'bob.build-box.web-1',
  session: 'bobsess',
  at: '2026-10-17T12:00:00.000Z',
});

/** Remove `user`'s permission block from the generated users.conf and reload (twice: a reload wires new imports only on the next one; here nothing is new, but it does no harm). */
async function stripPermissions(b: Broker, user: string): Promise<void> {
  const file = path.join(b.confDir, 'users.conf');
  const txt = fs.readFileSync(file, 'utf8');
  const re = new RegExp(
    `("USER_${user}" \\{[\\s\\S]*?)\\n {8}permissions: \\{[\\s\\S]*?\\n {8}\\}\\n`,
  );
  assert.match(txt, re, 'no permission block to strip');
  fs.writeFileSync(file, txt.replace(re, '$1\n'));
  b.reload();
  await sleep(300);
  b.reload();
  // While the server applies the reloads, a login can be refused: retry until the user may
  // subscribe to everything (only possible without the block).
  for (let i = 0; i < 150; i++) {
    const nc = await b.conn(user).catch(() => null);
    if (nc) {
      const free = await new Promise<boolean>((resolve) => {
        const sub = nc.subscribe('>');
        void sub.closed.then(() => resolve(false));
        nc.flush().then(
          () => sleep(200).then(() => resolve(!sub.isClosed())),
          () => resolve(false),
        );
      });
      await nc.close().catch(() => {});
      if (free) return;
    }
    await sleep(100);
  }
  throw new Error(`${user} still has a permission block after the reload`);
}

/** The highest sequence of every stream, to audit what a test made them store. */
async function positions(jsm: JetStreamManager): Promise<Record<string, number>> {
  const out: Record<string, number> = {};
  for (const s of STREAMS) out[s] = (await jsm.streams.info(s)).state.last_seq;
  return out;
}

/**
 * The subjects stored since `since` whose writer is not `user`: the presence key's user for a
 * presence subject, the feed's owner for an events subject (a foreign one if it is not the
 * feed's own), the admin for a sharing-list key, else the sender token (the last one), whichever
 * stream holds it.
 */
async function foreignWrites(
  jsm: JetStreamManager,
  since: Record<string, number>,
  user: string,
): Promise<{ foreign: string[]; own: number }> {
  const foreign: string[] = [];
  let own = 0;
  for (const s of STREAMS) {
    const last = (await jsm.streams.info(s)).state.last_seq;
    for (let seq = (since[s] ?? 0) + 1; seq <= last; seq++) {
      const m = await jsm.streams.getMessage(s, { seq }).catch(() => null);
      if (!m) continue; // replaced (presence keeps one entry per key)
      const t = m.subject.split('.');
      // A feed or the sharing bucket holds only its own subjects: anything else stored there is
      // foreign, whoever's name it carries (see the push-consumer test for the one tolerated case).
      const writer = s.startsWith('EVT_')
        ? t.length === 3 && t[0] === 'evt' && `EVT_${(t[1] ?? '').toUpperCase()}` === s
          ? t[1]
          : '(not this feed)'
        : s === 'KV_sharing'
          ? '(the admin, or not the sharing list)'
          : m.subject.startsWith('$KV.presence.')
            ? t[2]
            : t[t.length - 1];
      if (writer === user) own++;
      else foreign.push(`${s}#${seq} ${m.subject}`);
    }
  }
  return { foreign, own };
}

describe('per-user account isolation', { skip: SERVER.skip }, () => {
  let b: Broker;
  let alice: NatsConnection;
  let mallory: NatsConnection;
  let admin: NatsConnection;
  let ajs: JetStreamClient;
  let jsm: JetStreamManager;
  before(async () => {
    b = new Broker(SERVER);
    await b.init(['alice', 'bob', 'mallory']);
    await stripPermissions(b, 'mallory');
    alice = await b.conn('alice');
    mallory = await b.conn('mallory');
    admin = await b.conn('admin');
    ajs = jetstream(alice, { checkAPI: false, timeout: 15000 });
    jsm = await jetstreamManager(admin);
    // fixtures owned by bob: a message in his stream and a durable consumer on it
    const bob = await b.conn('bob');
    await jetstream(bob, { checkAPI: false }).publish(
      'mbx.bob.build-box.web-1.bob',
      'secret for bob',
    );
    // bob's service address bob.helpdesk: a claim, mail queued for it and its consumer
    await jetstream(bob, { checkAPI: false }).publish(BOB_CLAIM_SUBJECT, BOB_CLAIM);
    await jetstream(bob, { checkAPI: false }).publish(
      'mbx.bob._svc.helpdesk.bob',
      'secret for bob.helpdesk',
    );
    await bob.close();
    await jsm.consumers.add('MBX_BOB', {
      durable_name: 'bobsess',
      ack_policy: 'explicit',
      filter_subjects: ['mbx.bob.build-box.web-1.*'],
    });
    await jsm.consumers.add('MBX_BOB', {
      durable_name: 'svc=helpdesk',
      ack_policy: 'explicit',
      filter_subjects: ['mbx.bob._svc.helpdesk.*'],
    });
  });

  /** bob's claim and service consumer are as the fixtures left them. */
  async function bobServiceIntact(): Promise<void> {
    const claim = await jsm.streams.getMessage('KV_presence', { last_by_subj: BOB_CLAIM_SUBJECT });
    assert.equal(claim?.string(), BOB_CLAIM, "bob's claim was changed");
    const svc = await jsm.consumers.info('MBX_BOB', 'svc=helpdesk');
    assert.equal(svc.ack_floor.stream_seq, 0, "bob's service consumer was acked by someone else");
    assert.equal(svc.delivered.stream_seq, 0, "bob's service mail was pulled by someone else");
  }
  after(async () => {
    await alice?.close();
    await mallory?.close();
    await admin?.close();
    await b?.stop();
  });

  /** A request alice sends must be refused by the server's permissions (not by JetStream). */
  async function denied(subject: string, body: unknown = ''): Promise<void> {
    await assert.rejects(
      alice.request(subject, enc(body), { timeout: 15000 }),
      /Permissions Violation for Publish to/,
      subject,
    );
  }
  /** A core subscription alice makes must be refused. */
  async function subDenied(subject: string): Promise<void> {
    const sub = alice.subscribe(subject);
    const res = await Promise.race([sub.closed, sleep(2000).then(() => 'still open')]);
    assert.ok(
      res instanceof Error && /Permissions Violation for Subscription/.test(res.message),
      `${subject}: ${String(res)}`,
    );
  }
  async function count(stream: string): Promise<number> {
    return (await jsm.streams.info(stream)).state.messages;
  }

  describe('negative: alice cannot', () => {
    it("core-subscribe to bob's mail subjects or his reply inbox", async () => {
      await subDenied('mbx.bob.>');
      await subDenied('mbx.bob.build-box.web-1.alice');
      await subDenied('_INBOX_bob.>');
      await subDenied('>');
    });
    it('create a consumer on MBX_BOB (any API form)', async () => {
      const cfg = { stream_name: 'MBX_BOB', config: { durable_name: 'x', ack_policy: 'explicit' } };
      await denied('$JS.API.CONSUMER.DURABLE.CREATE.MBX_BOB.x', cfg);
      await denied('$JS.API.CONSUMER.CREATE.MBX_BOB.x', cfg);
      await denied('$JS.API.CONSUMER.CREATE.MBX_BOB.x.mbx.bob.>', cfg);
      await denied('$JS.API.CONSUMER.CREATE.MBX_BOB', {
        stream_name: 'MBX_BOB',
        config: { ack_policy: 'none' },
      });
    });
    it("read or delete bob's consumer", async () => {
      await denied('$JS.API.CONSUMER.INFO.MBX_BOB.bobsess');
      await denied('$JS.API.CONSUMER.MSG.NEXT.MBX_BOB.bobsess', { batch: 1 });
      await denied('$JS.API.CONSUMER.DELETE.MBX_BOB.bobsess');
      await denied('$JS.API.CONSUMER.NAMES.MBX_BOB');
      await denied('$JS.API.CONSUMER.LIST.MBX_BOB');
    });
    it('direct-get or message-get from MBX_BOB', async () => {
      await denied('$JS.API.DIRECT.GET.MBX_BOB', { seq: 1 });
      await denied('$JS.API.DIRECT.GET.MBX_BOB.mbx.bob.build-box.web-1.bob');
      await denied('$JS.API.STREAM.MSG.GET.MBX_BOB', { seq: 1 });
    });
    it('get stream info for MBX_BOB, or list streams', async () => {
      await denied('$JS.API.STREAM.INFO.MBX_BOB');
      await denied('$JS.API.STREAM.NAMES');
      await denied('$JS.API.STREAM.LIST');
    });
    it('purge, delete or update MBX_ALL or her own stream, or delete messages in them', async () => {
      for (const s of ['MBX_ALL', 'MBX_ALICE']) {
        await denied(`$JS.API.STREAM.PURGE.${s}`, {});
        await denied(`$JS.API.STREAM.DELETE.${s}`);
        await denied(`$JS.API.STREAM.UPDATE.${s}`, { name: s, subjects: ['mbx.>'] });
        await denied(`$JS.API.STREAM.MSG.DELETE.${s}`, { seq: 1 });
      }
      await denied('$JS.API.STREAM.CREATE.MBX_EVIL', { name: 'MBX_EVIL', subjects: ['mbx.bob.>'] });
    });
    it('create consumers on the shared broadcast stream or the presence bucket', async () => {
      await denied('$JS.API.CONSUMER.DURABLE.CREATE.MBX_ALL.x', {
        stream_name: 'MBX_ALL',
        config: { durable_name: 'x', ack_policy: 'none' },
      });
      await denied('$JS.API.CONSUMER.CREATE.MBX_ALL.x', {
        stream_name: 'MBX_ALL',
        config: { name: 'x', ack_policy: 'none' },
      });
      await denied('$JS.API.CONSUMER.CREATE.KV_presence.x', {
        stream_name: 'KV_presence',
        config: { name: 'x', ack_policy: 'none' },
      });
    });
    it('publish with a spoofed sender token', async () => {
      const before = await count('MBX_BOB');
      const asks = await count('ASKS');
      await assert.rejects(ajs.publish('mbx.bob.h.l.bob', 'spoof'), /Permissions Violation/);
      await assert.rejects(ajs.publish('mbx.bob.h.l.carol', 'spoof'), /Permissions Violation/);
      await assert.rejects(ajs.publish('mbx.all.bob', 'spoof'), /Permissions Violation/);
      await assert.rejects(ajs.publish('mbx.bob.h.l', 'short'), /Permissions Violation/);
      for (const subject of [`ask.${T}.bob`, `ask.${T}.carol`, `ask.${T}`, `ask.${T}.alice.x`])
        await assert.rejects(ajs.publish(subject, 'spoof'), /Permissions Violation/, subject);
      assert.equal(await count('MBX_BOB'), before);
      assert.equal(await count('ASKS'), asks);
    });
    it('create, read or delete consumers on the asks stream, or purge, delete, update or query it', async () => {
      const cfg = { stream_name: 'ASKS', config: { durable_name: 'x', ack_policy: 'none' } };
      for (const [subject, body] of [
        ['$JS.API.CONSUMER.DURABLE.CREATE.ASKS.x', cfg],
        ['$JS.API.CONSUMER.CREATE.ASKS.x', cfg],
        ['$JS.API.CONSUMER.CREATE.ASKS', cfg],
        ['$JS.API.CONSUMER.MSG.NEXT.ASKS.x', { batch: 1 }],
        ['$JS.API.CONSUMER.INFO.ASKS.x', ''],
        ['$JS.API.CONSUMER.DELETE.ASKS.x', ''],
        ['$JS.API.CONSUMER.NAMES.ASKS', ''],
        ['$JS.API.STREAM.PURGE.ASKS', {}],
        ['$JS.API.STREAM.DELETE.ASKS', ''],
        ['$JS.API.STREAM.UPDATE.ASKS', { name: 'ASKS', subjects: ['ask.>'] }],
        ['$JS.API.STREAM.MSG.DELETE.ASKS', { seq: 1 }],
        ['$JS.API.STREAM.MSG.GET.ASKS', { seq: 1 }],
        ['$JS.API.STREAM.INFO.ASKS', ''], // not needed: asks are read by direct get
        [`$JS.API.DIRECT.GET.ASKS.ask.${T}.bob`, ''], // only the batch form is granted
        ['$JS.API.STREAM.CREATE.ASKS_EVIL', { name: 'ASKS_EVIL', subjects: ['ask.*.bob'] }],
      ] as Array<[string, unknown]>)
        await denied(subject, body);
      await subDenied('mbxwake.ask.>');
      assert.equal((await jsm.streams.info('ASKS')).config.name, 'ASKS');
    });
    it('rely on the asks stream accepting deletes, purges, rollups or literal subjects', async () => {
      const cfg = (await jsm.streams.info('ASKS')).config;
      assert.equal(cfg.deny_delete, true);
      assert.equal(cfg.deny_purge, true);
      assert.equal(cfg.allow_rollup_hdrs, false);
      assert.deepEqual(cfg.subjects, ['ask.*.*']); // a wildcard: no push-consumer deliveries
      assert.equal(cfg.allow_direct, true);
      assert.equal(cfg.max_age, 7 * 86400 * 1_000_000_000);
      assert.deepEqual(cfg.republish, {
        src: 'ask.*.*',
        dest: 'mbxwake.ask.{{wildcard(1)}}.{{wildcard(2)}}',
        headers_only: true,
      });
    });
    it("claim, release, take over or read bob's service address, or spoof mail into it", async () => {
      const since = await positions(jsm);
      const del = headers();
      del.set('KV-Operation', 'DEL');
      const cas = headers();
      cas.set('Nats-Expected-Last-Subject-Sequence', '0');
      for (const [subject, data, h] of [
        [BOB_CLAIM_SUBJECT, enc({ ...JSON.parse(BOB_CLAIM), session: 'alice-1' }), undefined],
        [BOB_CLAIM_SUBJECT, '', del],
        [BOB_CLAIM_SUBJECT, '{}', cas],
        ['$KV.presence.bob._svc.other', '{}', cas], // a new claim in bob's name
        ['mbx.bob._svc.helpdesk.bob', 'spoof', undefined],
        ['mbx.bob._svc.helpdesk.carol', 'spoof', undefined],
        ['mbx.bob._svc.helpdesk', 'short', undefined],
      ] as Array<[string, string, ReturnType<typeof headers> | undefined]>)
        await assert.rejects(
          ajs.publish(subject, data, h ? { headers: h } : {}),
          /Permissions Violation/,
          subject,
        );
      const svc = {
        stream_name: 'MBX_BOB',
        config: { durable_name: 'svc=helpdesk', ack_policy: 'explicit' },
      };
      for (const [subject, body] of [
        ['$JS.API.CONSUMER.DURABLE.CREATE.MBX_BOB.svc=helpdesk', svc],
        ['$JS.API.CONSUMER.CREATE.MBX_BOB.svc=helpdesk', svc],
        ['$JS.API.CONSUMER.INFO.MBX_BOB.svc=helpdesk', ''],
        ['$JS.API.CONSUMER.MSG.NEXT.MBX_BOB.svc=helpdesk', { batch: 1 }],
        ['$JS.API.CONSUMER.DELETE.MBX_BOB.svc=helpdesk', ''],
        ['$JS.ACK.MBX_BOB.svc=helpdesk.1.1.1.1.1', '+ACK'],
        ['$JS.API.DIRECT.GET.MBX_BOB', { seq: 1, next_by_subj: 'mbx.bob._svc.helpdesk.*' }],
        ['$JS.API.DIRECT.GET.MBX_BOB.mbx.bob._svc.helpdesk.bob', ''],
        ['$JS.API.STREAM.MSG.GET.MBX_BOB', { last_by_subj: 'mbx.bob._svc.helpdesk.bob' }],
        ['$JS.API.STREAM.PURGE.MBX_BOB', { filter: 'mbx.bob._svc.helpdesk.*' }],
        ['$JS.API.STREAM.MSG.DELETE.MBX_BOB', { seq: 1 }],
        ['$JS.API.STREAM.PURGE.KV_presence', { filter: BOB_CLAIM_SUBJECT }],
      ] as Array<[string, unknown]>)
        await denied(subject, body);
      await subDenied('mbx.bob._svc.>');
      await subDenied('mbx.*._svc.helpdesk.*');
      await subDenied('$KV.presence.bob._svc.*');
      assert.deepEqual((await foreignWrites(jsm, since, 'alice')).foreign, []);
      await bobServiceIntact();
    });
    it("write bob's presence entries", async () => {
      const h = headers();
      h.set('KV-Operation', 'DEL');
      await assert.rejects(
        ajs.publish('$KV.presence.bob.build-box.abc', '{}'),
        /Permissions Violation/,
      );
      await assert.rejects(
        ajs.publish('$KV.presence.bob.build-box.abc', '', { headers: h }),
        /Permissions Violation/,
      );
    });
    it("purge everyone's presence entries with a rollup on her own key", async () => {
      const bob = await b.conn('bob');
      await jetstream(bob, { checkAPI: false }).publish('$KV.presence.bob.desk.keep', '{}');
      await bob.close();
      const h = headers();
      h.set('Nats-Rollup', 'all');
      await assert.rejects(
        ajs.publish('$KV.presence.alice.laptop.roll', '{}', { headers: h }),
        /rollup/i,
      );
      const m = await jsm.streams.getMessage('KV_presence', {
        last_by_subj: '$KV.presence.bob.desk.keep',
      });
      assert.ok(m, "bob's entry is gone");
    });
    it('forge into another stream, the JetStream API or the wake-ups through a push consumer', async () => {
      // A push consumer lives in the stream account, so its deliveries are published there. It
      // delivers only while something there listens on its deliver subject, which nothing does in
      // production; here the admin listens on each target, so the deliveries really happen. A
      // delivery keeps the stored message's own subject (the deliver subject only routes it), so
      // a stream that captures it stores it under alice's own name; API subjects ignore it.
      await ajs.publish(
        'mbx.alice.laptop.x.alice',
        JSON.stringify({ v: 1, id: 'f1', from: 'carol.h.x', body: 'forged' }),
      );
      await ajs.publish(
        'mbx.alice.laptop.x.alice',
        JSON.stringify({ name: 'MBX_EVIL', subjects: ['mbx.evil.>'] }),
      );
      const streamNames = async () => {
        const names: string[] = [];
        for await (const n of jsm.streams.names()) names.push(n);
        return names.sort();
      };
      const since = await positions(jsm);
      const namesBefore = await streamNames();
      const bob = await b.conn('bob');
      const woken: string[] = [];
      for (const wake of ['mbx.all.*', 'ask.*.*'])
        bob.subscribe(wake, { callback: (_e, m) => void woken.push(m.subject) });
      await bob.flush();
      const targets = [
        'mbx.bob.h.l.carol',
        'mbx.all.carol',
        '$KV.presence.carol.h.x',
        'evt.bob.h',
        '$KV.sharing.team',
        'mbxwake.all.carol',
        `ask.${T}.carol`,
        `mbxwake.ask.${T}.carol`,
        '$JS.API.STREAM.CREATE.MBX_EVIL',
        '$JS.API.STREAM.DELETE.MBX_BOB',
        '$JS.API.STREAM.PURGE.MBX_ALL',
        '$JS.API.CONSUMER.DELETE.MBX_BOB.bobsess',
        'mbx.bob._svc.helpdesk.carol',
        BOB_CLAIM_SUBJECT,
        '$JS.API.CONSUMER.DELETE.MBX_BOB.svc=helpdesk',
      ];
      const listening = targets
        .filter((t) => !t.startsWith('mbxwake.')) // see below: no interest from the admin there
        .map((t) => admin.subscribe(t));
      await admin.flush();
      let n = 0;
      for (const target of targets) {
        const r = await alice.request(
          `$JS.API.CONSUMER.DURABLE.CREATE.MBX_ALICE.p${++n}`,
          enc({
            stream_name: 'MBX_ALICE',
            config: {
              durable_name: `p${n}`,
              deliver_subject: target,
              ack_policy: 'none',
              deliver_policy: 'all',
              filter_subject: 'mbx.alice.laptop.x.*',
            },
          }),
          { timeout: 15000 },
        );
        assert.ok(r.string().length > 0);
      }
      // control: the same kind of consumer does deliver, inside the stream account (where only the
      // admin can listen), never into alice's account
      const ctl = admin.subscribe('ctl.push', { max: 1 });
      const own = alice.subscribe('_INBOX_alice.ctl', { max: 1 });
      await admin.flush();
      for (const [name, target] of [
        ['c0', 'ctl.push'],
        ['c1', '_INBOX_alice.ctl'],
      ])
        await alice.request(
          `$JS.API.CONSUMER.DURABLE.CREATE.MBX_ALICE.${name}`,
          enc({
            stream_name: 'MBX_ALICE',
            config: {
              durable_name: name,
              deliver_subject: target,
              ack_policy: 'none',
              deliver_policy: 'all',
              filter_subject: 'mbx.alice.laptop.x.*',
            },
          }),
          { timeout: 15000 },
        );
      for await (const m of ctl) assert.match(m.string(), /forged/);
      await sleep(1500);
      assert.equal(own.getReceived(), 0, 'a push delivery reached alice in her own account');
      own.unsubscribe();
      assert.ok(
        listening.some((sub) => sub.getReceived() > 0),
        'no push consumer delivered: the test proves nothing',
      );
      for (const sub of listening) sub.unsubscribe();
      // With the admin listening, a feed, the sharing bucket or the asks stream captures the
      // deliveries aimed at it; they keep alice's own mail subject, which their readers ignore
      // (feeds are read as evt.<owner>.*, the list as its one key, asks as ask.<token>.*). In
      // production nothing listens, so nothing is delivered at all ("events feed isolation"
      // proves that). In ASKS such a capture counts as alice's own write: its subject ends in her
      // name.
      const tolerated = /^(EVT_BOB|KV_sharing)#\d+ mbx\.alice\.laptop\.x\.alice$/;
      const { foreign } = await foreignWrites(jsm, since, 'alice');
      assert.deepEqual(
        foreign.filter((f) => !tolerated.test(f)),
        [],
      );
      assert.deepEqual(await streamNames(), namesBefore);
      assert.ok((await jsm.consumers.info('MBX_BOB', 'bobsess')).name === 'bobsess');
      await bobServiceIntact();
      // Without interest in the stream account, a consumer aimed at a wake-up export delivers
      // nothing (an import's interest does not count). Were that to change, a user could send
      // everyone extra wake-ups under any name: clients ignore a wake-up's content and only poll.
      assert.deepEqual(woken, [], 'a push delivery reached bob as a broadcast or ask wake-up');
      await bob.close();
    });
    it('authenticate with a wrong password or anonymously', async () => {
      await assert.rejects(
        connect({
          servers: b.url,
          user: 'alice',
          pass: 'wrong-password-1234',
          reconnect: false,
          timeout: 10000,
        }),
        /Authorization Violation/i,
      );
      await assert.rejects(
        connect({ servers: b.url, reconnect: false, timeout: 10000 }),
        /Authorization Violation/i,
      );
    });
  });

  describe('negative: reply subjects and imports (alice, and mallory without a permission block)', () => {
    /**
     * Every request a user may send, each with every hostile reply subject. Before per-user
     * accounts, the server published the response to the reply subject inside the shared account,
     * where bob's stream, the broadcast stream or the presence bucket stored it under carol's name.
     */
    async function injectEverywhere(nc: NatsConnection, user: string): Promise<void> {
      const S = `MBX_${user.toUpperCase()}`;
      const E = `EVT_${user.toUpperCase()}`;
      const js = jetstream(nc, { checkAPI: false, timeout: 15000 });
      const forged = enc({ v: 1, id: `forged-${user}`, from: 'carol.h.x', body: 'spoof' });
      const pa = await js.publish(`mbx.${user}.h.x.${user}`, forged);
      const forgedEvent = enc({ event: 'done', address: 'bob.h.forged', status: 'forged' });
      const pe = await js.publish(`evt.${user}.h`, forgedEvent);
      await js.publish(`$KV.presence.${user}.h.s1`, forged);
      const pk = await js.publish(`ask.${T}.${user}`, forged);
      const consumer = enc({
        stream_name: S,
        config: {
          durable_name: 'inj',
          ack_policy: 'explicit',
          ack_wait: 600_000_000_000,
          filter_subjects: [`mbx.${user}.h.x.*`],
        },
      });
      await nc.request(`$JS.API.CONSUMER.DURABLE.CREATE.${S}.inj`, consumer, { timeout: 15000 });
      const svcConsumer = enc({
        stream_name: S,
        config: {
          durable_name: 'svc=desk',
          ack_policy: 'explicit',
          filter_subjects: [`mbx.${user}._svc.desk.*`],
        },
      });
      const claim = enc({ service: `${user}.desk`, holder: `${user}.h.x`, session: 's1', at: '' });
      const requests: Array<[string, string]> = [
        [`$JS.API.DIRECT.GET.${S}`, enc({ seq: pa.seq })],
        [`$JS.API.DIRECT.GET.${S}`, enc({ seq: 1, batch: 5 })],
        [`$JS.API.DIRECT.GET.${S}.mbx.${user}.h.x.${user}`, ''],
        ['$JS.API.DIRECT.GET.MBX_ALL', enc({ seq: 1, batch: 3 })],
        ['$JS.API.DIRECT.GET.KV_presence', enc({ multi_last: ['$KV.presence.>'] })],
        [`$JS.API.DIRECT.GET.KV_presence.$KV.presence.${user}.h.s1`, ''],
        ['$JS.API.INFO', ''],
        [`$JS.API.STREAM.INFO.${S}`, ''],
        ['$JS.API.STREAM.INFO.MBX_ALL', ''],
        [`$JS.API.CONSUMER.INFO.${S}.inj`, ''],
        [`$JS.API.CONSUMER.DURABLE.CREATE.${S}.inj`, consumer],
        [`$JS.API.CONSUMER.MSG.NEXT.${S}.inj`, enc({ batch: 5, no_wait: true })],
        [`mbx.bob.h.x.${user}`, forged], // the publish acknowledgement goes to the reply
        [`mbx.all.${user}`, forged],
        [`$KV.presence.${user}.h.s2`, forged],
        [`$JS.API.DIRECT.GET.${E}`, enc({ seq: pe.seq })],
        [`$JS.API.DIRECT.GET.${E}`, enc({ seq: 1, batch: 5, next_by_subj: `evt.${user}.*` })],
        ['$JS.API.DIRECT.GET.EVT_BOB', enc({ seq: 1 })], // bob's feed is shared with the team
        ['$JS.API.DIRECT.GET.KV_sharing.$KV.sharing.team', ''],
        [`evt.${user}.h`, forgedEvent],
        ['$JS.API.DIRECT.GET.ASKS', enc({ seq: pk.seq })],
        ['$JS.API.DIRECT.GET.ASKS', enc({ seq: 1, batch: 5, next_by_subj: `ask.${T}.*` })],
        [`ask.${T}.${user}`, forged],
        // service addresses: mail to bob's and to the own one, the own claim, reading claims and
        // the own service consumer
        [`mbx.bob._svc.helpdesk.${user}`, forged],
        [`mbx.${user}._svc.desk.${user}`, forged],
        [`$KV.presence.${user}._svc.desk`, claim],
        [`$JS.API.DIRECT.GET.KV_presence.${BOB_CLAIM_SUBJECT}`, ''],
        ['$JS.API.DIRECT.GET.KV_presence', enc({ multi_last: ['$KV.presence.*._svc.*'] })],
        [`$JS.API.CONSUMER.DURABLE.CREATE.${S}.svc=desk`, svcConsumer],
        [`$JS.API.CONSUMER.INFO.${S}.svc=desk`, ''],
        [`$JS.API.CONSUMER.MSG.NEXT.${S}.svc=desk`, enc({ batch: 5, no_wait: true })],
      ];
      const replies = [
        'mbx.bob.h.l.carol',
        'mbx.all.carol',
        '$KV.presence.carol.h.x',
        `mbx.${user}.h.l.carol`, // a forged sender in the attacker's own stream
        'mbx.carol.h.l.bob',
        'mbxwake.all.carol',
        '$JS.API.DIRECT.GET.MBX_BOB',
        '_INBOX_bob.x',
        '$JS.ACK.MBX_BOB.bobsess.1.1.1.1.1',
        'evt.bob.h',
        '$KV.sharing.team',
        '$JS.API.DIRECT.GET.EVT_BOB',
        `ask.${T}.carol`,
        `ask.${T}.bob`,
        `mbxwake.ask.${T}.carol`,
        '$JS.API.DIRECT.GET.ASKS',
        'mbx.bob._svc.helpdesk.carol',
        `mbx.${user}._svc.desk.carol`, // a forged sender to the attacker's own service
        BOB_CLAIM_SUBJECT,
        '$KV.presence.carol._svc.helpdesk',
        '$JS.API.CONSUMER.DURABLE.CREATE.MBX_BOB.svc=helpdesk',
        '$JS.ACK.MBX_BOB.svc=helpdesk.1.1.1.1.1',
      ];
      // a real delivery, acknowledged below with hostile replies (the ack's own response). Not
      // multiplexed: a pulled message keeps its own subject, which the shared inbox cannot route.
      const next = await nc.request(
        `$JS.API.CONSUMER.MSG.NEXT.${S}.inj`,
        enc({ batch: 1, expires: 5_000_000_000 }),
        { timeout: 15000, noMux: true },
      );
      const ack = next.reply ?? '';
      assert.ok(ack.startsWith(`$JS.ACK.${S}.inj.`), `no delivery to ack: ${ack}`);
      await js.publish(`mbx.${user}.h.x.${user}`, forged); // something left for MSG.NEXT below
      for (const [subject, body] of requests)
        for (const reply of replies) nc.publish(subject, body, { reply });
      for (const reply of replies) nc.publish(ack, '+ACK', { reply });
      await nc.flush();
    }

    for (const user of ['alice', 'mallory']) {
      it(`${user}: no reply to any request is stored under another user's name`, async () => {
        const nc = user === 'alice' ? alice : mallory;
        const since = await positions(jsm);
        // mallory can listen to her own account: the responses do arrive there, on the hostile subjects
        const home = user === 'mallory' ? mallory.subscribe('mbx.bob.h.l.carol') : null;
        await injectEverywhere(nc, user);
        await sleep(1500);
        const { foreign, own } = await foreignWrites(jsm, since, user);
        assert.deepEqual(foreign, []);
        assert.ok(own >= 3, `the requests were not served (${own} own writes)`);
        if (home) {
          assert.ok(home.getReceived() > 0, "the responses never reached mallory's own account");
          home.unsubscribe();
        }
        const bobsess = await jsm.consumers.info('MBX_BOB', 'bobsess');
        assert.equal(bobsess.ack_floor.stream_seq, 0, "bob's consumer was acked by someone else");
        await bobServiceIntact();
      });
    }

    it("mallory gets no answer from another user's API surface", async () => {
      const since = await positions(jsm);
      const bobsess = await jsm.consumers.info('MBX_BOB', 'bobsess');
      const probes: Array<[string, unknown]> = [
        ['$JS.API.DIRECT.GET.MBX_BOB', { seq: 1 }],
        ['$JS.API.DIRECT.GET.MBX_BOB.mbx.bob.build-box.web-1.bob', ''],
        ['$JS.API.STREAM.INFO.MBX_BOB', ''],
        ['$JS.API.STREAM.MSG.GET.MBX_BOB', { seq: 1 }],
        ['$JS.API.STREAM.NAMES', ''],
        ['$JS.API.STREAM.LIST', ''],
        ['$JS.API.CONSUMER.INFO.MBX_BOB.bobsess', ''],
        ['$JS.API.CONSUMER.LIST.MBX_BOB', ''],
        ['$JS.API.CONSUMER.MSG.NEXT.MBX_BOB.bobsess', { batch: 5, no_wait: true }],
        [
          '$JS.API.CONSUMER.DURABLE.CREATE.MBX_BOB.evil',
          { stream_name: 'MBX_BOB', config: { durable_name: 'evil', ack_policy: 'explicit' } },
        ],
        [
          '$JS.API.CONSUMER.CREATE.MBX_ALL',
          { stream_name: 'MBX_ALL', config: { ack_policy: 'none' } },
        ],
        ['$JS.API.CONSUMER.DELETE.MBX_BOB.bobsess', ''],
        ['$JS.ACK.MBX_BOB.bobsess.1.1.1.1.1', '+ACK'],
        ['$JS.API.STREAM.PURGE.MBX_ALL', {}],
        ['$JS.API.STREAM.DELETE.MBX_BOB', ''],
        ['$JS.API.STREAM.MSG.DELETE.MBX_ALL', { seq: 1 }],
        ['$JS.API.STREAM.CREATE.MBX_EVIL', { name: 'MBX_EVIL', subjects: ['mbx.bob.>'] }],
        ['$KV.presence.bob.h.x', '{}'],
        ['$JS.API.STREAM.INFO.EVT_BOB', ''],
        ['$JS.API.STREAM.MSG.GET.EVT_BOB', { seq: 1 }],
        ['$JS.API.CONSUMER.CREATE.EVT_BOB', { stream_name: 'EVT_BOB', config: {} }],
        ['$JS.API.STREAM.PURGE.EVT_BOB', {}],
        ['$JS.API.DIRECT.GET.EVT_BOB.evt.bob.h', ''],
        ['$JS.API.DIRECT.GET.KV_sharing', { seq: 1 }],
        ['$JS.API.DIRECT.GET.KV_sharing.$KV.sharing.bob', ''],
        ['$JS.API.STREAM.PURGE.KV_sharing', {}],
        ['$KV.sharing.team', '["mallory"]'],
        ['evt.bob.h', '{}'],
        ['$JS.API.STREAM.INFO.ASKS', ''],
        ['$JS.API.STREAM.MSG.GET.ASKS', { seq: 1 }],
        ['$JS.API.CONSUMER.CREATE.ASKS', { stream_name: 'ASKS', config: {} }],
        [
          '$JS.API.CONSUMER.DURABLE.CREATE.ASKS.evil',
          { stream_name: 'ASKS', config: { durable_name: 'evil', ack_policy: 'none' } },
        ],
        ['$JS.API.STREAM.PURGE.ASKS', {}],
        ['$JS.API.STREAM.DELETE.ASKS', ''],
        ['$JS.API.STREAM.MSG.DELETE.ASKS', { seq: 1 }],
        ['$JS.API.STREAM.UPDATE.ASKS', { name: 'ASKS', subjects: ['ask.>'] }],
        [`$JS.API.DIRECT.GET.ASKS.ask.${T}.bob`, ''],
        [`ask.${T}.bob`, '{}'],
        ['$JS.API.DIRECT.GET.MBX_BOB.mbx.bob._svc.helpdesk.bob', ''],
        ['$JS.API.CONSUMER.INFO.MBX_BOB.svc=helpdesk', ''],
        ['$JS.API.CONSUMER.MSG.NEXT.MBX_BOB.svc=helpdesk', { batch: 5, no_wait: true }],
        [
          '$JS.API.CONSUMER.DURABLE.CREATE.MBX_BOB.svc=helpdesk',
          {
            stream_name: 'MBX_BOB',
            config: { durable_name: 'svc=helpdesk', ack_policy: 'explicit' },
          },
        ],
        ['$JS.API.CONSUMER.DELETE.MBX_BOB.svc=helpdesk', ''],
        ['$JS.ACK.MBX_BOB.svc=helpdesk.1.1.1.1.1', '+ACK'],
        ['$JS.API.STREAM.PURGE.MBX_BOB', { filter: 'mbx.bob._svc.helpdesk.*' }],
        ['$JS.API.STREAM.PURGE.KV_presence', { filter: BOB_CLAIM_SUBJECT }],
        [BOB_CLAIM_SUBJECT, '{}'],
      ];
      const answers = await Promise.all(
        probes.map(([subject, body]) =>
          mallory.request(subject, enc(body), { timeout: 3000 }).then(
            (m) => `${subject}: answered ${m.string().slice(0, 80)}`,
            () => null, // no responders or no answer: nothing in her account serves it
          ),
        ),
      );
      assert.deepEqual(
        answers.filter((a) => a !== null),
        [],
      );
      assert.deepEqual((await foreignWrites(jsm, since, 'mallory')).foreign, []);
      const after = await jsm.consumers.info('MBX_BOB', 'bobsess');
      assert.deepEqual(after.delivered, bobsess.delivered);
      assert.deepEqual(after.ack_floor, bobsess.ack_floor);
      assert.equal((await jsm.streams.info('MBX_BOB')).config.name, 'MBX_BOB');
      await bobServiceIntact();
    });

    it('mallory cannot publish under another name through any import', async () => {
      const mjs = jetstream(mallory, { checkAPI: false, timeout: 3000 });
      const since = await positions(jsm);
      for (const subject of [
        'mbx.bob.h.l.carol',
        'mbx.bob.h.l.bob',
        'mbx.all.carol',
        'mbx.bob.h.l',
        'mbx.bob.h.l.mallory.x',
        '$KV.presence.carol.h.x',
        '$KV.presence.bob',
        'evt.bob.h',
        'evt.bob',
        'evt.mallory',
        'evt.mallory.h.x',
        '$KV.sharing.team',
        `ask.${T}.carol`,
        `ask.${T}.bob`,
        `ask.${T}`,
        `ask.${T}.mallory.x`,
        `mbxwake.ask.${T}.bob`,
        'mbx.bob._svc.helpdesk.carol',
        'mbx.bob._svc.helpdesk.bob',
        'mbx.bob._svc.helpdesk',
        BOB_CLAIM_SUBJECT,
        '$KV.presence.bob._svc.other',
        '$KV.presence.carol._svc.helpdesk',
      ])
        await assert.rejects(mjs.publish(subject, 'spoof'), subject);
      await bobServiceIntact();
      assert.deepEqual((await foreignWrites(jsm, since, 'mallory')).foreign, []);
    });

    it("mallory, listening to everything in her account, hears none of the others' traffic", async () => {
      const heard: string[] = [];
      for (const p of [
        '>',
        '$JS.>',
        '_R_.>',
        '_INBOX_bob.>',
        '_INBOX_alice.>',
        '$KV.>',
        'mbxwake.>',
      ])
        mallory.subscribe(p, {
          callback: (_e, m) => void heard.push(`${p} <- ${m.subject} (${m.data.length} bytes)`),
        });
      await mallory.flush();
      const bob = await b.conn('bob');
      const bjs = jetstream(bob, { checkAPI: false, timeout: 15000 });
      const bjsm = await jetstreamManager(bob, { checkAPI: false, timeout: 15000 });
      await ajs.publish('mbx.bob.build-box.web-1.alice', 'private to bob');
      await bjs.publish('mbx.alice.laptop.web-3.bob', 'private to alice');
      await ajs.publish('$KV.presence.alice.laptop.zz', '{"address":"alice.laptop.zz"}');
      await bjsm.direct.getMessage('MBX_BOB', { seq: 1 });
      await bjsm.consumers.add('MBX_BOB', {
        durable_name: 'bobsniff',
        ack_policy: 'explicit',
        filter_subjects: ['mbx.bob.build-box.web-1.*'],
      });
      const m = await (await bjs.consumers.get('MBX_BOB', 'bobsniff')).next({ expires: 3000 });
      assert.ok(m);
      await m.ackAck();
      await ajs.publish('mbx.all.alice', 'hello everyone');
      await bjs.publish(`ask.${T}.bob`, 'a question for the team');
      await sleep(1000);
      await bob.close();
      // the wake-ups, headers only (two streams: no order between them)
      assert.deepEqual(heard.sort(), [
        `> <- ask.${T}.bob (0 bytes)`,
        '> <- mbx.all.alice (0 bytes)',
      ]);
    });
  });

  describe('positive: alice can', () => {
    let broadcastSeq = 0;
    it('send to bob and broadcast (stamped with her user)', async () => {
      const pa = await ajs.publish('mbx.bob.build-box.web-1.alice', 'hi bob', { msgID: 'pos-1' });
      assert.equal(pa.stream, 'MBX_BOB');
      const pb = await ajs.publish('mbx.all.alice', 'hi all', { msgID: 'pos-2' });
      assert.equal(pb.stream, 'MBX_ALL');
      broadcastSeq = pb.seq;
      const dup = await ajs.publish('mbx.all.alice', 'hi all', { msgID: 'pos-2' });
      assert.equal(dup.duplicate, true); // publish retries are deduped by envelope id
    });
    it('wake bob with a broadcast: headers only, stamped with her user', async () => {
      const bob = await b.conn('bob');
      const sub = bob.subscribe('mbx.all.*', { max: 1 });
      await bob.flush();
      await ajs.publish('mbx.all.alice', 'wake up', { msgID: 'pos-3' });
      for await (const m of sub) {
        assert.equal(m.subject, 'mbx.all.alice');
        assert.equal(m.data.length, 0);
        assert.equal(m.headers?.get('Nats-Stream'), 'MBX_ALL');
      }
      await bob.close();
    });
    it('read her own stream through her own durable consumer, and ack', async () => {
      await ajs.publish('mbx.alice.laptop.web-2.alice', 'note to self');
      const ajsm = await jetstreamManager(alice, { checkAPI: false });
      await ajsm.consumers.add('MBX_ALICE', {
        durable_name: 'mine',
        ack_policy: 'explicit',
        filter_subjects: ['mbx.alice.laptop.web-2.*'],
      });
      const c = await ajs.consumers.get('MBX_ALICE', 'mine');
      const m = await c.next({ expires: 3000 });
      assert.ok(m);
      assert.equal(m.string(), 'note to self');
      assert.equal(await m.ackAck(), true);
      await ajsm.consumers.update('MBX_ALICE', 'mine', {
        filter_subjects: ['mbx.alice.laptop.web-2.*', 'mbx.alice.laptop.alias.*'],
      });
      assert.equal((await ajsm.streams.info('MBX_ALICE')).config.name, 'MBX_ALICE');
      const d = await ajsm.direct.getMessage('MBX_ALICE', { seq: m.seq });
      assert.ok(d);
      assert.equal(d.string(), 'note to self');
      await assert.rejects(ajsm.consumers.delete('MBX_ALICE', 'mine'), /Permissions Violation/); // not needed, not granted
    });
    it('ask in an area (stamped with her user, deduped), wake bob with headers only, and read asks by direct get', async () => {
      const bob = await b.conn('bob');
      const sub = bob.subscribe(`ask.${T}.*`, { max: 1 });
      await bob.flush();
      const pa = await ajs.publish(`ask.${T}.alice`, 'how do I run the tests?', { msgID: 'ask-1' });
      assert.equal(pa.stream, 'ASKS');
      const dup = await ajs.publish(`ask.${T}.alice`, 'how do I run the tests?', {
        msgID: 'ask-1',
      });
      assert.equal(dup.duplicate, true);
      for await (const m of sub) {
        assert.equal(m.subject, `ask.${T}.alice`);
        assert.equal(m.data.length, 0);
        assert.equal(m.headers?.get('Nats-Stream'), 'ASKS');
      }
      const bjsm = await jetstreamManager(bob, { checkAPI: false });
      const it2 = await bjsm.direct.getBatch('ASKS', {
        seq: pa.seq, // earlier tests stored asks in this area too
        batch: 10,
        next_by_subj: `ask.${T}.*`,
      });
      const got: string[] = [];
      for await (const m of it2) got.push(`${m.subject} ${m.string()}`);
      assert.ok(got.includes(`ask.${T}.alice how do I run the tests?`), got.join('\n'));
      await bob.close();
    });
    it("claim her own service address once (compare-and-set), read anyone's claims, and read its mail, stamped with the sender, through its own consumer", async () => {
      const cas = headers();
      cas.set('Nats-Expected-Last-Subject-Sequence', '0');
      const claim = enc({
        service: 'alice.ledger',
        holder: 'alice.laptop.x',
        session: 's',
        at: '',
      });
      await ajs.publish('$KV.presence.alice._svc.ledger', claim, { headers: cas });
      await assert.rejects(
        ajs.publish('$KV.presence.alice._svc.ledger', claim, { headers: cas }),
        /wrong last sequence/,
      );
      const ajsm = await jetstreamManager(alice, { checkAPI: false });
      const bobs = await ajsm.direct.getMessage('KV_presence', { last_by_subj: BOB_CLAIM_SUBJECT });
      assert.equal(bobs?.string(), BOB_CLAIM);
      const bob = await b.conn('bob');
      const pa = await jetstream(bob, { checkAPI: false }).publish(
        'mbx.alice._svc.ledger.bob',
        'a request for alice.ledger',
      );
      await bob.close();
      assert.equal(pa.stream, 'MBX_ALICE');
      await ajsm.consumers.add('MBX_ALICE', {
        durable_name: 'svc=ledger',
        ack_policy: 'explicit',
        deliver_policy: 'all',
        filter_subjects: ['mbx.alice._svc.ledger.*'],
      });
      const m = await (await ajs.consumers.get('MBX_ALICE', 'svc=ledger')).next({ expires: 3000 });
      assert.ok(m);
      assert.equal(m.subject, 'mbx.alice._svc.ledger.bob');
      assert.equal(m.string(), 'a request for alice.ledger');
      assert.equal(await m.ackAck(), true);
    });
    it('read broadcasts by direct get, write her own presence entry and read the whole bucket', async () => {
      const ajsm = await jetstreamManager(alice, { checkAPI: false });
      const it2 = await ajsm.direct.getBatch('MBX_ALL', {
        seq: broadcastSeq,
        batch: 10,
        next_by_subj: 'mbx.all.*',
      });
      const got: string[] = [];
      for await (const m of it2) got.push(m.string());
      assert.ok(got.includes('hi all'));
      await ajs.publish('$KV.presence.alice.laptop.abc', '{"address":"alice.laptop.x"}');
      const it3 = await ajsm.direct.getLastMessagesFor('KV_presence', {
        multi_last: ['$KV.presence.>'],
      });
      const keys: string[] = [];
      for await (const m of it3) keys.push(m.subject);
      assert.ok(keys.includes('$KV.presence.alice.laptop.abc'));
    });
  });
});

describe('admin script', { skip: SERVER.skip }, () => {
  let b: Broker;
  before(async () => {
    b = new Broker(SERVER);
    await b.init(['alice', 'bob']);
  });
  after(async () => {
    await b?.stop();
  });
  /** alice can still reach the stream account through her imports. */
  async function aliceWorks(): Promise<void> {
    const nc = await b.conn('alice');
    try {
      const pa = await jetstream(nc, { checkAPI: false }).publish(
        'mbx.bob.h.l.alice',
        'still here',
      );
      assert.equal(pa.stream, 'MBX_BOB');
    } finally {
      await nc.close();
    }
  }

  it('add-user / list-users / remove-user take effect through a live reload', async () => {
    const out = b.addUser('carol');
    assert.match(out, /created stream MBX_CAROL/);
    assert.match(out, /reloaded nats-server/);
    assert.deepEqual(b.admin(['list-users']).out.trim().split('\n'), ['alice', 'bob', 'carol']);
    const carol = await b.conn('carol');
    await jetstream(carol, { checkAPI: false }).publish('mbx.alice.laptop.x.carol', 'hi alice');
    await carol.close();
    await aliceWorks();
    assert.match(b.admin(['remove-user', 'carol']).out, /removed user carol/);
    let still = true; // the reload signal is asynchronous
    for (let i = 0; i < 20 && still; i++)
      still = await b.conn('carol').then(
        (nc) =>
          nc
            .close()
            .then(() => sleep(100))
            .then(() => true),
        () => false,
      );
    await assert.rejects(b.conn('carol'), /Authorization Violation/i);
    await aliceWorks(); // removing an account leaves the others' imports alone
    assert.doesNotMatch(fs.readFileSync(path.join(b.confDir, 'users.conf'), 'utf8'), /carol/);
    assert.notEqual(b.admin(['add-user', 'all'], { check: false }).code, 0); // reserved
    assert.notEqual(b.admin(['add-user', 'Bad_Name'], { check: false }).code, 0);
    assert.notEqual(b.admin(['add-user', 'alice'], { check: false }).code, 0); // exists
  });

  it('permissions shows the account a user gets, without changing anything', () => {
    const conf = path.join(b.confDir, 'users.conf');
    const before = fs.readFileSync(conf, 'utf8');
    const perms = b.admin(['permissions', 'dave']).out;
    assert.match(perms, /"USER_dave" \{/);
    assert.match(perms, /service: "mbx\.\*\.\*\.\*\.dave", accounts: \["USER_dave"\]/);
    assert.match(
      perms,
      /\{ service: \{ account: "MAILBOX", subject: "\$JS\.ACK\.MBX_DAVE\.>" \} \}/,
    );
    assert.match(perms, /"mbx\.\*\.\*\.\*\.dave"/);
    assert.match(perms, /"_INBOX_dave\.>"/);
    assert.doesNotMatch(perms, /jetstream/);
    assert.equal(fs.readFileSync(conf, 'utf8'), before);
  });

  it('the generated config gives each user exactly their own surface', () => {
    const conf = fs.readFileSync(path.join(b.confDir, 'users.conf'), 'utf8');
    // every export of a user's own subjects is restricted to that user's account, except the
    // read of their events feed, which goes to every account while it is shared with the team
    const feed = /service: "\$JS\.API\.DIRECT\.GET\.EVT_ALICE"/;
    for (const line of conf.split('\n').filter((l) => /service: "[^"]*(ALICE|alice)[^"]*"/.test(l)))
      if (!feed.test(line)) assert.match(line, /accounts: \["USER_alice"\] \}$/, line);
    assert.match(
      conf,
      /service: "\$JS\.API\.DIRECT\.GET\.EVT_ALICE", response_type: stream, accounts: \["USER_alice", "USER_bob"\] \}/,
    );
    const aliceAccount = /"USER_alice" \{[\s\S]*?\n {2}\}\n/.exec(conf)?.[0] ?? '';
    assert.ok(aliceAccount, 'no USER_alice account');
    assert.doesNotMatch(aliceAccount, /jetstream/);
    // bob appears in alice's account only as the read of his shared feed (import and block)
    const bobLines = aliceAccount.split('\n').filter((l) => /BOB|bob/.test(l));
    assert.equal(bobLines.length, 2, bobLines.join('\n'));
    for (const l of bobLines) assert.match(l, /\$JS\.API\.DIRECT\.GET\.EVT_BOB"/, l);
    assert.equal(conf.match(/jetstream: enabled/g)?.length, 1); // only the stream account
  });

  it('init on a running, provisioned server neither reloads it nor touches anything', async () => {
    const conf = path.join(b.confDir, 'users.conf');
    const before = fs.readFileSync(conf, 'utf8');
    const jsm = await jetstreamManager(await b.conn('admin'));
    const allBefore = (await jsm.streams.info('MBX_ALL')).config;
    const out = b.admin(['init']).out;
    assert.match(out, /users\.conf unchanged: no server reload needed/);
    assert.doesNotMatch(out, /reloaded nats-server|upgrading|republishes|refuses/);
    assert.match(out, /stream MBX_ALL already exists \(kept\)/);
    assert.match(out, /kv bucket presence already exists \(kept\)/);
    assert.equal(fs.readFileSync(conf, 'utf8'), before);
    assert.deepEqual((await jsm.streams.info('MBX_ALL')).config, allBefore);
    assert.equal((await jsm.streams.info('KV_presence')).config.name, 'KV_presence');
  });

  it('a users.d file with something other than a bcrypt hash never reaches the server', () => {
    const conf = path.join(b.confDir, 'users.conf');
    const before = fs.readFileSync(conf, 'utf8');
    const evil = path.join(b.confDir, 'users.d', 'eve.conf');
    for (const pw of ['plaintext', '$2a$11$abc" } ] permissions: { ', ''])
      try {
        fs.writeFileSync(evil, `  {\n    user: "eve"\n    password: "${pw}"\n  }\n`);
        const r = b.admin(['init'], { check: false });
        assert.notEqual(r.code, 0, pw);
        assert.match(r.out, /password hash/);
        assert.equal(fs.readFileSync(conf, 'utf8'), before);
      } finally {
        fs.rmSync(evil, { force: true });
      }
  });

  it('init recreates a stream that the server loses right after a reload', async () => {
    // A second server, so the shared one keeps its admin credentials. The `nats` CLI is wrapped so
    // that the first `stream add MBX_ALL` is followed by deleting the stream again: what a reload
    // finishing late does to a freshly created stream.
    const b2 = new Broker(SERVER);
    try {
      await b2.init([]);
      const nc = await b2.conn('admin');
      const jsm = await jetstreamManager(nc);
      await jsm.streams.delete('MBX_ALL');
      await jsm.streams.delete('KV_presence');
      await nc.close();
      // A new admin user changes users.conf, so init reloads the server.
      fs.rmSync(path.join(b2.confDir, 'admin.creds'));
      fs.rmSync(path.join(b2.confDir, 'users.d', '_admin.conf'));
      const shim = path.join(b2.dir, 'nats-shim.sh');
      fs.writeFileSync(
        shim,
        `#!/bin/sh\n"$REAL_NATS" "$@"; rc=$?\n` +
          `if [ "$1 $2 $3" = "stream add MBX_ALL" ] && [ ! -f "$MARK" ]; then touch "$MARK"; "$REAL_NATS" stream rm -f MBX_ALL >/dev/null 2>&1; fi\n` +
          `exit $rc\n`,
        { mode: 0o755 },
      );
      const env = {
        NATS_BIN: shim,
        REAL_NATS: SERVER.natsBin,
        MARK: path.join(b2.dir, 'lost-once'),
        MBOX_RELOAD_SETTLE: '0.2',
      };
      const out = b2.admin(['init'], { env }).out;
      assert.match(out, /reloaded nats-server/);
      assert.ok(fs.existsSync(env.MARK), 'the shim never ran: the test proves nothing');
      assert.match(out, /lost during the server reload; recreating it/);
      const nc2 = await b2.conn('admin'); // the new admin credentials
      try {
        const jsm2 = await jetstreamManager(nc2);
        const all = await jsm2.streams.info('MBX_ALL');
        assert.equal(all.config.republish?.dest, 'mbxwake.all.{{wildcard(1)}}');
        assert.equal((await jsm2.streams.info('KV_presence')).config.name, 'KV_presence');
      } finally {
        await nc2.close();
      }
    } finally {
      await b2.stop();
    }
  });
});

// Events feeds: EVT_<USER>, written only by <user>, readable by another user only while the admin
// shares it with the team (set-sharing), through a service export to exactly those accounts. bob
// shares (the default); carol is private. alice has the permission block the script generates;
// mallory's is stripped, so that her account's imports are the only boundary.
describe('events feed isolation', { skip: SERVER.skip }, () => {
  let b: Broker;
  let alice: NatsConnection;
  let mallory: NatsConnection;
  let admin: NatsConnection;
  let ajs: JetStreamClient;
  let jsm: JetStreamManager;
  const ev = (user: string, n: number, address = `${user}.box.s-${n}`): string =>
    JSON.stringify({ event: 'started', address, user, at: '' });
  before(async () => {
    b = new Broker(SERVER);
    await b.init(['alice', 'bob', 'carol', 'mallory']);
    b.admin(['set-sharing', 'carol', 'private']);
    await stripPermissions(b, 'mallory');
    for (const u of ['bob', 'carol']) {
      const nc = await b.conn(u);
      await jetstream(nc, { checkAPI: false }).publish(`evt.${u}.box`, ev(u, 1));
      await nc.close();
    }
    alice = await b.conn('alice');
    mallory = await b.conn('mallory');
    admin = await b.conn('admin');
    ajs = jetstream(alice, { checkAPI: false, timeout: 15000 });
    jsm = await jetstreamManager(admin);
  });
  after(async () => {
    await alice?.close();
    await mallory?.close();
    await admin?.close();
    await b?.stop();
  });

  /** A request alice sends must be refused by the server's permissions (her block). */
  async function denied(subject: string, body: unknown = ''): Promise<void> {
    await assert.rejects(
      alice.request(subject, enc(body), { timeout: 15000 }),
      /Permissions Violation for Publish to/,
      subject,
    );
  }
  /** Requests mallory sends that nothing in her account answers (no import serves them). */
  async function unanswered(probes: Array<[string, unknown]>): Promise<void> {
    const answers = await Promise.all(
      probes.map(([subject, body]) =>
        mallory.request(subject, enc(body), { timeout: 3000 }).then(
          (m) => `${subject}: answered ${m.string().slice(0, 80)}`,
          () => null,
        ),
      ),
    );
    assert.deepEqual(
      answers.filter((a) => a !== null),
      [],
    );
  }
  async function subDenied(subject: string): Promise<void> {
    const sub = alice.subscribe(subject);
    const res = await Promise.race([sub.closed, sleep(2000).then(() => 'still open')]);
    assert.ok(
      res instanceof Error && /Permissions Violation for Subscription/.test(res.message),
      `${subject}: ${String(res)}`,
    );
  }
  async function count(stream: string): Promise<number> {
    return (await jsm.streams.info(stream)).state.messages;
  }
  /** Every event in a feed, read the way the client reads it (batch direct get). */
  async function readFeed(nc: NatsConnection, user: string): Promise<string[]> {
    const njsm = await jetstreamManager(nc, { checkAPI: false });
    const it = await njsm.direct.getBatch(`EVT_${user.toUpperCase()}`, {
      seq: 1,
      batch: 100,
      next_by_subj: `evt.${user}.*`,
    });
    const out: string[] = [];
    for await (const m of it) out.push(m.string());
    return out;
  }
  /**
   * Whether `nc` may read `user`'s feed. A refused batch get is never answered (a timeout), so
   * this asks with one single get: refused at once by the permission block (alice), or answered
   * by nobody in the account (mallory, no import).
   */
  async function canRead(nc: NatsConnection, user: string): Promise<boolean> {
    const njsm = await jetstreamManager(nc, { checkAPI: false, timeout: 3000 });
    return njsm.direct.getMessage(`EVT_${user.toUpperCase()}`, { seq: 1 }).then(
      () => true,
      (e: unknown) => {
        if (/Permissions Violation|no responders|503|timeout/i.test(String(e))) return false;
        throw e;
      },
    );
  }
  async function sharingList(nc: NatsConnection): Promise<unknown> {
    const njsm = await jetstreamManager(nc, { checkAPI: false });
    const m = await njsm.direct.getMessage('KV_sharing', { last_by_subj: '$KV.sharing.team' });
    return m ? (JSON.parse(m.string()) as unknown) : null;
  }
  const FEEDS = ['EVT_ALICE', 'EVT_BOB', 'EVT_CAROL', 'EVT_MALLORY'];

  describe('negative: alice and mallory cannot', () => {
    it("read carol's private feed (any API form)", async () => {
      await denied('$JS.API.DIRECT.GET.EVT_CAROL', { seq: 1 });
      await denied('$JS.API.DIRECT.GET.EVT_CAROL', {
        seq: 1,
        batch: 10,
        next_by_subj: 'evt.carol.*',
      });
      await denied('$JS.API.DIRECT.GET.EVT_CAROL.evt.carol.box');
      await denied('$JS.API.STREAM.MSG.GET.EVT_CAROL', { seq: 1 });
      await denied('$JS.API.STREAM.INFO.EVT_CAROL');
      assert.equal(await canRead(alice, 'carol'), false);
      await unanswered([
        ['$JS.API.DIRECT.GET.EVT_CAROL', { seq: 1 }],
        ['$JS.API.DIRECT.GET.EVT_CAROL', { seq: 1, batch: 10, next_by_subj: 'evt.carol.*' }],
        ['$JS.API.DIRECT.GET.EVT_CAROL', { multi_last: ['evt.carol.*'] }],
        ['$JS.API.DIRECT.GET.EVT_CAROL.evt.carol.box', ''],
        ['$JS.API.STREAM.MSG.GET.EVT_CAROL', { seq: 1 }],
        ['$JS.API.STREAM.INFO.EVT_CAROL', ''],
      ]);
      assert.equal(await canRead(mallory, 'carol'), false);
    });
    it("core-subscribe to anyone's events (alice), or hear any of them (mallory)", async () => {
      await subDenied('evt.carol.*');
      await subDenied('evt.bob.box');
      await subDenied('evt.alice.*');
      await subDenied('evt.>');
      const heard: string[] = [];
      mallory.subscribe('>', { callback: (_e, m) => void heard.push(m.subject) });
      await mallory.flush();
      const bob = await b.conn('bob');
      await jetstream(bob, { checkAPI: false }).publish('evt.bob.box', ev('bob', 7));
      await ajs.publish('evt.alice.box', ev('alice', 7));
      await bob.close();
      await sleep(1000);
      assert.deepEqual(heard, []);
    });
    it("write another user's feed", async () => {
      const before = await Promise.all(FEEDS.map(count));
      const mjs = jetstream(mallory, { checkAPI: false, timeout: 3000 });
      for (const subj of [
        'evt.bob.box',
        'evt.carol.box',
        'evt.bob',
        'evt.bob.box.x',
        'evt.all.box',
      ]) {
        await assert.rejects(ajs.publish(subj, ev('bob', 9)), /Permissions Violation/, subj);
        await assert.rejects(mjs.publish(subj, ev('bob', 9)), subj);
      }
      for (const subj of ['evt.alice', 'evt.alice.box.x'])
        await assert.rejects(ajs.publish(subj, ev('alice', 9)), /Permissions Violation/, subj);
      for (const subj of ['evt.mallory', 'evt.mallory.box.x'])
        await assert.rejects(mjs.publish(subj, ev('mallory', 9)), subj);
      assert.deepEqual(await Promise.all(FEEDS.map(count)), before);
    });
    it('create, read or delete consumers on any feed, their own and shared ones included', async () => {
      const probes: Array<[string, unknown]> = [];
      for (const s of FEEDS) {
        const cfg = { stream_name: s, config: { durable_name: 'x', ack_policy: 'none' } };
        probes.push(
          [`$JS.API.CONSUMER.DURABLE.CREATE.${s}.x`, cfg],
          [`$JS.API.CONSUMER.CREATE.${s}.x`, cfg],
          [`$JS.API.CONSUMER.CREATE.${s}`, cfg],
          [`$JS.API.CONSUMER.MSG.NEXT.${s}.x`, { batch: 1 }],
          [`$JS.API.CONSUMER.INFO.${s}.x`, ''],
          [`$JS.API.CONSUMER.DELETE.${s}.x`, ''],
          [`$JS.API.CONSUMER.NAMES.${s}`, ''],
        );
      }
      for (const [subject, body] of probes) await denied(subject, body);
      await unanswered(probes);
    });
    it('purge, delete, update or query any feed, or delete events in one', async () => {
      const probes: Array<[string, unknown]> = [];
      for (const s of FEEDS)
        probes.push(
          [`$JS.API.STREAM.PURGE.${s}`, {}],
          [`$JS.API.STREAM.DELETE.${s}`, ''],
          [`$JS.API.STREAM.UPDATE.${s}`, { name: s, subjects: ['evt.>'] }],
          [`$JS.API.STREAM.MSG.DELETE.${s}`, { seq: 1 }],
          [`$JS.API.STREAM.INFO.${s}`, ''], // not needed: feeds are read by direct get
        );
      probes.push([
        '$JS.API.STREAM.CREATE.EVT_EVIL',
        { name: 'EVT_EVIL', subjects: ['evt.bob.*'] },
      ]);
      for (const [subject, body] of probes) await denied(subject, body);
      await unanswered(probes);
      assert.deepEqual(
        await Promise.all(FEEDS.map(async (s) => (await jsm.streams.info(s)).config.name)),
        FEEDS,
      );
    });
    it('write the sharing list, or read any of it but the team key', async () => {
      const before = await count('KV_sharing');
      const mjs = jetstream(mallory, { checkAPI: false, timeout: 3000 });
      for (const subj of ['$KV.sharing.team', '$KV.sharing.alice', '$KV.sharing.x.y']) {
        await assert.rejects(ajs.publish(subj, '["alice","carol"]'), /Permissions Violation/, subj);
        await assert.rejects(mjs.publish(subj, '["mallory","carol"]'), subj);
      }
      assert.equal(await count('KV_sharing'), before);
      const probes: Array<[string, unknown]> = [
        ['$JS.API.DIRECT.GET.KV_sharing', { seq: 1 }],
        ['$JS.API.DIRECT.GET.KV_sharing', { multi_last: ['$KV.sharing.>'] }],
        ['$JS.API.DIRECT.GET.KV_sharing.$KV.sharing.carol', ''],
        ['$JS.API.DIRECT.GET.KV_sharing.$KV.sharing.>', ''],
        ['$JS.API.CONSUMER.CREATE.KV_sharing', { stream_name: 'KV_sharing', config: {} }],
        ['$JS.API.STREAM.PURGE.KV_sharing', {}],
        ['$JS.API.STREAM.INFO.KV_sharing', ''],
      ];
      for (const [subject, body] of probes) await denied(subject, body);
      await unanswered(probes);
      await subDenied('$KV.sharing.>');
    });
    it('deliver into a feed, the sharing list or the asks stream through a push consumer, with nothing listening', async () => {
      // Production: nothing in the stream account subscribes to a feed's, the list's or the asks' subjects,
      // and a stream with a wildcard subject does not count as a listener. The control, a stream on
      // a literal subject, does capture: the check could see a delivery.
      await jsm.streams.add({ name: 'TST_LIT', subjects: ['tst.lit'] });
      try {
        const targets = [
          'evt.bob.box',
          'evt.carol.box',
          'evt.alice.box',
          '$KV.sharing.team',
          `ask.${T}.bob`,
        ];
        const before = await Promise.all([...FEEDS, 'KV_sharing', 'ASKS'].map(count));
        for (const [nc, user] of [
          [alice, 'alice'],
          [mallory, 'mallory'],
        ] as const) {
          const S = `MBX_${user.toUpperCase()}`;
          await jetstream(nc, { checkAPI: false }).publish(`mbx.${user}.h.p.${user}`, ev('bob', 3));
          let n = 0;
          for (const target of [...targets, 'tst.lit'])
            await nc.request(
              `$JS.API.CONSUMER.DURABLE.CREATE.${S}.push${++n}`,
              enc({
                stream_name: S,
                config: {
                  durable_name: `push${n}`,
                  deliver_subject: target,
                  ack_policy: 'none',
                  deliver_policy: 'all',
                  filter_subject: `mbx.${user}.h.p.*`,
                },
              }),
              { timeout: 15000 },
            );
        }
        for (let i = 0; i < 300 && (await count('TST_LIT')) < 2; i++) await sleep(100);
        assert.equal(await count('TST_LIT'), 2, 'the control stream captured nothing');
        await sleep(1500);
        assert.deepEqual(await Promise.all([...FEEDS, 'KV_sharing', 'ASKS'].map(count)), before);
      } finally {
        await jsm.streams.delete('TST_LIT');
      }
    });
    it('reply-inject into a feed or the sharing list with any request they may send', async () => {
      // As on main for the mail streams: an allowed request whose reply subject is another
      // user's feed or the sharing list; the response must never be stored there.
      const since = await Promise.all([...FEEDS, 'KV_sharing'].map(count));
      for (const [nc, user] of [
        [alice, 'alice'],
        [mallory, 'mallory'],
      ] as const) {
        const js = jetstream(nc, { checkAPI: false, timeout: 15000 });
        const forged = ev('bob', 66, 'bob.box.forged');
        const pa = await js.publish(`evt.${user}.box`, forged);
        const U = user.toUpperCase();
        const requests: Array<[string, string]> = [
          [`$JS.API.DIRECT.GET.EVT_${U}`, enc({ seq: pa.seq })],
          [`$JS.API.DIRECT.GET.EVT_${U}`, enc({ seq: 1, batch: 5, next_by_subj: `evt.${user}.*` })],
          ['$JS.API.DIRECT.GET.EVT_BOB', enc({ seq: 1 })],
          ['$JS.API.DIRECT.GET.KV_sharing.$KV.sharing.team', ''],
          ['$JS.API.INFO', ''],
          [`evt.${user}.box`, forged], // the publish acknowledgement goes to the reply
        ];
        const replies = [
          'evt.bob.box',
          'evt.carol.forged',
          `evt.${user === 'alice' ? 'mallory' : 'alice'}.box`,
          '$KV.sharing.team',
          '$JS.API.DIRECT.GET.EVT_CAROL',
        ];
        for (const [subject, body] of requests)
          for (const reply of replies) nc.publish(subject, body, { reply });
        await nc.flush();
      }
      await sleep(1500);
      const after = await Promise.all([...FEEDS, 'KV_sharing'].map(count));
      // Each attacker's own feed grew by exactly their own six publishes (the forged event, and
      // the five acknowledged ones); every other feed and the sharing list by nothing.
      assert.deepEqual(
        after.map((n, i) => n - (since[i] ?? 0)),
        [6, 0, 0, 6, 0],
        'EVT_ALICE, EVT_BOB, EVT_CAROL, EVT_MALLORY, KV_sharing',
      );
    });
    it("read a feed once its owner's sharing is set to private (live reload), and again after team", async () => {
      assert.equal(await canRead(alice, 'bob'), true);
      assert.equal(await canRead(mallory, 'bob'), true);
      try {
        assert.match(b.admin(['set-sharing', 'bob', 'private']).out, /reloaded nats-server/);
        // The reload signal is asynchronous: wait for it to take effect.
        for (let i = 0; i < 300 && (await canRead(mallory, 'bob')); i++) await sleep(100);
        assert.equal(await canRead(alice, 'bob'), false);
        assert.equal(await canRead(mallory, 'bob'), false);
        await denied('$JS.API.DIRECT.GET.EVT_BOB', {
          seq: 1,
          batch: 10,
          next_by_subj: 'evt.bob.*',
        });
        assert.deepEqual(await sharingList(alice), ['alice', 'mallory']);
      } finally {
        b.admin(['set-sharing', 'bob', 'team']);
      }
      for (let i = 0; i < 300 && !(await canRead(mallory, 'bob')); i++) await sleep(100);
      assert.equal((await readFeed(alice, 'bob')).length >= 1, true);
      assert.equal((await readFeed(mallory, 'bob')).length >= 1, true);
    });
  });

  describe('positive', () => {
    it("alice reads her own feed and bob's shared one, and the sharing list (without carol)", async () => {
      assert.ok((await readFeed(alice, 'alice')).length >= 1);
      assert.match(await readFeed(alice, 'bob').then((l) => l[0] ?? ''), /bob\.box\.s-1/);
      assert.deepEqual(await sharingList(alice), ['alice', 'bob', 'mallory']);
    });
    it("mallory, without a permission block, reads bob's shared feed through her import", async () => {
      assert.match(await readFeed(mallory, 'bob').then((l) => l[0] ?? ''), /bob\.box\.s-1/);
      assert.deepEqual(await sharingList(mallory), ['alice', 'bob', 'mallory']);
    });
    it('carol reads her own private feed, and the shared ones', async () => {
      const carol = await b.conn('carol');
      try {
        assert.equal((await readFeed(carol, 'carol')).length, 1);
        assert.ok((await readFeed(carol, 'bob')).length >= 1);
      } finally {
        await carol.close();
      }
    });
  });

  describe('admin script', () => {
    it('set-sharing rejects bad input; list-users --sharing and permissions show the settings', () => {
      assert.notEqual(b.admin(['set-sharing', 'bob', 'public'], { check: false }).code, 0);
      assert.notEqual(b.admin(['set-sharing', 'nobody', 'team'], { check: false }).code, 0);
      assert.notEqual(b.admin(['set-sharing', 'bob'], { check: false }).code, 0);
      assert.deepEqual(b.admin(['list-users', '--sharing']).out.trim().split('\n'), [
        'alice team',
        'bob team',
        'carol private',
        'mallory team',
      ]);
      const perms = b.admin(['permissions', 'alice']).out;
      assert.match(perms, /"\$JS\.API\.DIRECT\.GET\.EVT_BOB"/);
      assert.doesNotMatch(perms, /EVT_CAROL/);
      assert.match(perms, /"evt\.alice\.\*",/);
      assert.match(perms, /service: "evt\.alice\.\*", accounts: \["USER_alice"\]/);
      assert.match(b.admin(['permissions', 'carol']).out, /EVT_ALICE[\s\S]*EVT_BOB/);
      // carol's feed is exported to her account alone; bob's to every account.
      const conf = fs.readFileSync(path.join(b.confDir, 'users.conf'), 'utf8');
      assert.match(
        conf,
        /service: "\$JS\.API\.DIRECT\.GET\.EVT_CAROL", response_type: stream, accounts: \["USER_carol"\] \}/,
      );
      assert.match(
        conf,
        /service: "\$JS\.API\.DIRECT\.GET\.EVT_BOB", response_type: stream, accounts: \["USER_bob", "USER_alice", "USER_carol", "USER_mallory"\] \}/,
      );
    });
    it('set-sharing to the current value does not reload the server', () => {
      const out = b.admin(['set-sharing', 'alice', 'team']).out;
      assert.match(out, /users\.conf unchanged: no server reload needed/);
      assert.doesNotMatch(out, /reloaded nats-server/);
    });
    it('add-user and remove-user keep every account and the sharing list in step', async () => {
      b.addUser('dave');
      try {
        assert.match(b.admin(['permissions', 'alice']).out, /EVT_DAVE/);
        assert.deepEqual(await sharingList(alice), ['alice', 'bob', 'dave', 'mallory']);
        // an existing account gains the import of the new user's feed
        const dave = await b.conn('dave');
        await jetstream(dave, { checkAPI: false }).publish('evt.dave.box', ev('dave', 1));
        await dave.close();
        for (let i = 0; i < 300 && !(await canRead(mallory, 'dave')); i++) await sleep(100);
        assert.equal((await readFeed(mallory, 'dave')).length, 1);
        assert.equal((await readFeed(alice, 'dave')).length, 1);
      } finally {
        assert.match(
          b.admin(['remove-user', 'dave', '--delete-stream']).out,
          /deleted stream EVT_DAVE/,
        );
      }
      assert.doesNotMatch(b.admin(['permissions', 'alice']).out, /EVT_DAVE/);
      assert.deepEqual(await sharingList(alice), ['alice', 'bob', 'mallory']);
    });
  });
});
